def solve():
    n = 8
    x = [0] * n
    x[0] = 0
    x[1] = 2

    def backtrack(idx, current_diffs):
        if idx == n:
            return True

        # Try values for x[idx]
        # To keep it reasonable, we can bound the max value. 
        # An optimal Golomb ruler of order 8 has length 34.
        # We can search up to 100.
        start_val = x[idx-1] + 1
        for val in range(start_val, 200):
            new_diffs = []
            valid = True
            for i in range(idx):
                diff = val - x[i]
                if diff in current_diffs:
                    valid = False
                    break
                new_diffs.append(diff)

            if valid:
                x[idx] = val
                for d in new_diffs:
                    current_diffs.add(d)

                if backtrack(idx + 1, current_diffs):
                    return True

                for d in new_diffs:
                    current_diffs.remove(d)

        return False

    diffs = set([2])
    if backtrack(2, diffs):
        print(x)
    else:
        print("UNSAT")

solve()
